import pandas as pd


def run(inputs: dict) -> dict:
    dim_store = inputs["dim_store"].copy()
    stg = inputs["stg_store_full"].copy()
    batch = inputs["batch_control"]

    b = batch["batch_date"].iloc[0]

    # Distinct (exact-duplicate) rows from the staging snapshot.
    S = stg.drop_duplicates(subset=["store_id", "region", "format"]).reset_index(drop=True)
    S_store_ids = set(S["store_id"])

    current_mask = dim_store["is_current"] == 1
    current_rows = dim_store[current_mask]

    # Map store_id -> current row (assume at most one current row per store_id)
    current_by_store = {}
    for _, row in current_rows.iterrows():
        current_by_store[row["store_id"]] = row

    def differs(a, bb):
        if pd.isna(a) and pd.isna(bb):
            return False
        return a != bb

    close_idx = []
    inserts = []

    for _, row in S.iterrows():
        sid = row["store_id"]
        if sid in current_by_store:
            c = current_by_store[sid]
            if differs(c["region"], row["region"]) or differs(c["format"], row["format"]):
                idx = dim_store[
                    (dim_store["store_id"] == sid) & (dim_store["is_current"] == 1)
                ].index
                close_idx.extend(idx.tolist())

                inserts.append({
                    "store_id": sid,
                    "region": row["region"],
                    "format": row["format"],
                    "eff_start_date": b,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                })
            # else: attributes unchanged -> no-op
        else:
            # brand-new store OR reopened store: always a new version
            inserts.append({
                "store_id": sid,
                "region": row["region"],
                "format": row["format"],
                "eff_start_date": b,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })

    # Close current rows for stores not present in the snapshot at all.
    for sid, c in current_by_store.items():
        if sid not in S_store_ids:
            idx = dim_store[
                (dim_store["store_id"] == sid) & (dim_store["is_current"] == 1)
            ].index
            close_idx.extend(idx.tolist())

    if close_idx:
        dim_store.loc[close_idx, "eff_end_date"] = b
        dim_store.loc[close_idx, "is_current"] = 0

    if inserts:
        insert_df = pd.DataFrame(inserts, columns=[
            "store_id", "region", "format", "eff_start_date", "eff_end_date", "is_current"
        ])
        dim_store = pd.concat([dim_store, insert_df], ignore_index=True)

    dim_store = dim_store.reset_index(drop=True)

    return {"dim_store_out": dim_store}
